 'R6-S34':FT({title:'The Effect of Strength Training Methods on Middle-Distance and Long-Distance Runners Athletic Performance: A Systematic Review with Meta-analysis',authors:'Llanos-Lagos C, Ramirez-Campillo R, Moran J, Saez de Villarreal E',year:2024,url:EPMC('PMC11258194'),doi:'10.1007/s40279-024-02018-z',pmid:'38627351',source_type:'META_ANALYSIS',population_design_dose:'Moderately to highly trained distance runners; strength programs 6-40 wk, 1-4 sessions/wk.',findings:'High-load and combined strength training improved running performance (ES -0.47 and -1.04); certainty very low to moderate.',locator:'Abstract Results.',limitations:['Very low to moderate certainty.'],counterevidence:['Plyometric training alone not significant.']}),
 'R6-S35':AB({title:'Does a run/walk strategy decrease cardiac stress during a marathon in non-elite runners?',authors:'Hottenrott K, Ludyga S, Schulze S, Gronwald T, Jager FS',year:2016,url:PUBMED('25467199'),doi:'10.1016/j.jsams.2014.11.010',pmid:'25467199',source_type:'RCT',population_design_dose:'42 non-elite runners (22 men, 20 women) randomized to a run/walk strategy or running only for a marathon; treadmill tests 7 days before and 4 days after.',findings:'Similar finish times (04:14:25 versus 04:07:40, p=0.377); cardiac biomarkers rose similarly in both groups; run/walk allowed similar times with less muscle discomfort.',locator:'Abstract only (Europe PMC core record; ssctr-evidence/abstracts-r7.json).',limitations:['Abstract only; marathon, not 10K or half marathon; trained finishers, not walk/jog novices.'],counterevidence:['Run/walk did not reduce cardiovascular load.']}),
 'R6-S36':AB({title:'Effects of tapering on performance: a meta-analysis',authors:'Bosquet L, Montpetit J, Arvisais D, Mujika I',year:2007,url:PUBMED('17762369'),doi:'10.1249/mss.0b013e31806010e0',pmid:'17762369',source_type:'META_ANALYSIS',population_design_dose:'27 studies of competitive athletes with defined tapers and competition or field performance.',findings:'A taper of about 2 weeks with training volume reduced exponentially by 41-60%, intensity and frequency maintained, was the most efficient strategy.',locator:'Abstract only (ssctr-evidence/abstracts-r7.json).',limitations:['Abstract only; competitive athletes; durations binned in days and weeks.'],counterevidence:['Optimal duration varies with prior load and individual.']}),
 'R6-S37':AB({title:'Scientific bases for precompetition tapering strategies',authors:'Mujika I, Padilla S',year:2003,url:PUBMED('12840640'),doi:'10.1249/01.mss.0000074448.73931.11',pmid:'12840640',source_type:'COMMENTARY_OPINION',population_design_dose:'Narrative review of tapering in athletes.',findings:'The taper is a progressive nonlinear reduction of training load during a variable period before competition (4 to more than 28 days); keep intensity, reduce volume, reduce frequency by no more than 20%; progressive tapers outperform step tapers.',locator:'Abstract only (ssctr-evidence/abstracts-r7.json).',limitations:['Abstract only; narrative review; athletes.'],counterevidence:['Durations are a wide range, not a rule.']}),
 'R6-S38':AB({title:'Are Trainees Lifting Heavy Enough? Self-Selected Loads in Resistance Exercise: A Scoping Review and Exploratory Meta-analysis',authors:'Steele J, Malleron T, Har-Nir I, Androulakis-Korakakis P, Wolf M, Fisher JP, Halperin I',year:2022,url:PUBMED('35790622'),doi:'10.1007/s40279-022-01717-9',pmid:'35790622',source_type:'META_ANALYSIS',population_design_dose:'18 studies, 368 healthy trainees selecting their own loads with a 1RM test.',findings:'On average trainees selected about 53% of 1RM (95% CrI 49-58%), with little moderation by experience, sex or age; heavier loads at lower repetition targets.',locator:'Abstract only (ssctr-evidence/abstracts-r7.json).',limitations:['Abstract only; mostly single sessions with vague instructions.'],counterevidence:['Load choice depends on the repetition target and instructions.']}),
