 reps:Q('TITLE:"progressive overload without progressing load"; TITLE:"accuracy in predicting repetitions to task failure"','Reps-then-load progression and RIR accuracy','Plotkin 2022 full text (R6-S11); Halperin 2022 abstract only (R6-S13).'),
 rirNovice:Q('TITLE_ABS:"repetitions in reserve" AND TITLE_ABS:"load" AND (novice OR untrained OR inexperienced)','Load establishment by RIR in less experienced lifters','8 hits; one open-access full text (R6-S12); others subscription-only.'),
 aeStrength:Q('TITLE_ABS:"aerobic exercise" AND "subsequent" AND "strength" AND "concurrent"','Residual effect of running on strength','6 hits; Markov 2022 full text (R6-S03).'),
 stRun:Q('TITLE_ABS:"muscle damage" AND "running performance" AND (resistance OR eccentric); TITLE:"impaired endurance performance following single bouts of resistance training"','Residual effect of lower-body strength on running','Doma 2019 and Assumpcao 2013 full text (R6-S09, R6-S10); Doma 2017 review abstract only (R6-S30).'),
 order:Q('TITLE:"intra-session exercise sequence"; TITLE:"concurrent" AND (sequence OR order) AND meta-analysis; TITLE_ABS:"concurrent training" AND (same day OR separate days)','Same-session order and spacing','Eddens 2018, Gao 2023, Lee 2020 full text (R6-S04/05/06); Robineau 2016 abstract only (R6-S31).'),
 compat:Q('Prior R4/R5 retrieval re-verified: PMC8891239, PMC9474354 (hash match with ssctr-access-trace.json)','Chronic concurrent compatibility and counterevidence','Schumann 2022 and Lundberg 2022 full text re-read (R6-S07, R6-S08).'),
 taper:Q('(TITLE:"tapering" OR TITLE:"taper") AND endurance AND performance; TITLE:"longer disciplined tapers"','Taper fractions and duration','Wang 2023 and Smyth 2021 full text (R6-S14, R6-S15); many off-topic surgical "taper" hits excluded.'),
 maint:Q('TITLE:"maintaining physical performance" OR (TITLE:"minimal dose" AND exercise)','Reduced strength dose near events','Spiering 2021 abstract only (R6-S16); Nuzzo 2024 full text (R6-S17).'),
 hmrec:Q('TITLE:"half-marathon" AND TITLE_ABS:"recovery"','Post-event recovery time course','26 hits; one open-access recreational-runner study (R6-S18).'),
 detrain:Q('TITLE:"detraining" AND (systematic review OR meta-analysis); TITLE:"training cessation" AND "muscular performance"','Return after interruption','Zheng 2022 full text (R6-S19); Bosquet 2013 abstract only (R6-S20); older-adult and clinical detraining reviews excluded as non-applicable.'),
 quality:Q('(TITLE:"recreational runners" OR TITLE:"recreational athletes") AND (polarized OR "intensity distribution"); sprint AND "running economy" AND "endurance runners"','Threshold and interval work in recreational runners','Festa 2020 and Garcia-Pinillos 2017 full text (R6-S22, R6-S23); Munoz 2014 not open access, not used.'),
 talk:Q('TITLE:"talk test"','Effort-anchored intensity','36 hits, mostly cardiac rehabilitation (excluded); one healthy-population validation used (R6-S24).'),
 indiv:Q('TITLE_ABS:"individualized" AND "endurance training" AND "recreational runners"','Response-gated progression','Nuuttila 2022 full text (R6-S21).'),
 runST:Q('TITLE:"strength training" AND "distance running" AND (meta-analysis OR systematic review)','Strength for runners','Blagrove 2018 and Llanos-Lagos 2024 full text (R6-S25, R6-S34).'),
 variation:Q('TITLE_ABS:"exercise variation" AND "resistance training" AND hypertrophy; TITLE_ABS:"exercise variation" AND "muscle thickness" AND motivation','Rotation and substitution','Baz-Valle 2019 full text (R6-S26); Kassiano 2022 abstract only (R6-S27).'),
 monitor:Q('Prior retrieval re-verified: PMC4789708, PMC8606564 (hash match)','Partial and noisy monitoring data','Saw 2016 and Bonafiglia 2021 full text (R6-S32, R6-S33).'),
 acsm:Q('Prior retrieval re-verified: PMC12965823 (hash match)','Current resistance-training position stand','ACSM 2026 full text re-read for progression, failure, volume, variation, individualization (R6-S01).'),
 r7taper:Q('TITLE:"effects of tapering on performance" AND meta-analysis; TITLE:"precompetition tapering"; TITLE:"taper" AND ("recreational runners" OR "10 km" OR "half-marathon")','Round 7: is event proximity a matter of days before competition','Wang 2023 (R6-S14, full text re-read), Bosquet 2007 and Mujika 2003 abstracts (R6-S36, R6-S37); one 2000 half-marathon taper study not open access and not used.'),
 r7runwalk:Q('TITLE:"run/walk strategy" OR TITLE:"run-walk strategy"; TITLE:"walk breaks" AND (marathon OR race); (TITLE:"walk-run" OR TITLE:"run-walk" OR TITLE:"walk/run") AND (injur* OR novice OR beginner)','Round 7: race day for walk/jog-prepared athletes; counterevidence on intermittent running','Hottenrott 2016 abstract (R6-S35); "walk breaks" 0 hits; walk-run hits were knee osteoarthritis, metabolic syndrome or field-test studies, not applicable.'),
 r7selfload:Q('TITLE:"self-selected" AND TITLE:"resistance" AND (intensity OR load)','Round 7: what a logged load above the plan means','23 hits; Steele 2022 and Barbosa-Netto 2021 abstracts (R6-S38, R6-S39); case reports, postmenopausal and affect studies not applicable.'),
 r7novice:Q('TITLE:"novice runners" AND (injury OR "running-related") AND (program OR progression)','Round 7: counterevidence for a raised walk/jog start','28 hits; no study of walk/jog entry steps or intermittent-versus-continuous exposure; Buist 2008 and Frandsen 2025 (R6-S28, R6-S02) remain the applicable evidence.')
