 'R6-S44':FT({title:'Integrating Deloading into Strength and Physique Sports Training Programmes: An International Delphi Consensus Approach',authors:'Bell L, Strafford BW, Coleman M, Androulakis Korakakis P, Nolan D',year:2023,url:EPMC('PMC10511399'),doi:'10.1186/s40798-023-00633-0',pmid:'37730925',source_type:'COMMENTARY_OPINION',prescriptive_support_eligible:false,population_design_dose:'Three-round online Delphi of expert strength and physique coaches (34, 29 and 21 respondents); 138 statements rated for agreement.',findings:'Consensus definition: deloading is a period of reduced training stress designed to mitigate fatigue, promote recovery and enhance preparedness for subsequent training; lowering sets was an agreed way to reduce volume; coaches agreed that a deload affords an opportunity to increase training demand in the subsequent cycle.',locator:'Abstract; Results (design and implementation statements, volume reduction by lowering sets); Discussion (definition, subsequent training cycle) (ssctr-evidence/PMC10511399.xml).',limitations:['Expert opinion of practitioners, not outcome evidence; strength and physique sports, not hybrid recreational athletes.'],counterevidence:['Autoregulated deloading may reduce the need for pre-planned deloads; effects on subsequent strength are not established.']}),
